    end--[[APR_DIAG]])--[[/APR_DIAG]])
    button:SetScript("OnLeave", --[[APR_DIAG]]APRTrace("APR-Core/features/player/Heirloom.lua:161:callback#15", --[[/APR_DIAG]]function(self) GameTooltip:Hide() end--[[APR_DIAG]])--[[/APR_DIAG]])

    return button
end--[[APR_DIAG]]; CreateMapButton = APRTrace("APR-Core/features/player/Heirloom.lua:142:CreateMapButton#13", CreateMapButton)--[[/APR_DIAG]]

function APR.heirloom:AddHeirloomIcons()
    if InCombatLockdown() then
        self._pendingCombatRefresh = true
        EnsureHeirloomCombatWatcher()
        return
    end
    local mapId = C_Map.GetBestMapForUnit("player")
    if not mapId or APR:GetHeirloomWarning() then
        return
    end
    local heirlooms = {
        {
            -- icon = "interface\\icons\\inv_misc_map09",
            name = "map",
            id = 150744,
            faction = "Horde"
        },
        {
            name = "map",
            id = 150745,
            faction = "Horde"
        },
        {
            name = "map",
            id = 150743,
            faction = "Alliance"
        },
        {
            name = "map",
            id = 150746,
            faction = "Alliance"
        },
        {
            name = "map",
            id = 187869,
            faction = "Neutral"
        },
        {
            name = "map",
            id = 187875,
            faction = "Neutral"
        },
        {
            name = "map",
            id = 187895,
            faction = "Neutral"
        },
        {
            name = "map",
            id = 187896,
            faction = "Neutral"
        },
        {
            name = "map",
            id = 187897,
            faction = "Neutral"
        },
        {
            name = "map",
            id = 187898,
            faction = "Neutral"
        },
        {
            name = "map",
            id = 187899,
            faction = "Neutral"
        },
        {
            name = "map",
            id = 187900,
            faction = "Neutral"
        },
        {
            icon = "Interface\\Icons\\inv_icon_heirloomtoken_armor01",
            name = "heirloom",
            id = 0,
        }
    }

    local xOffset = 5
    local yOffset = -5
    local maxElementsPerLine = 4
    local elementsCount = 0

    if next(self.buttons) then
        for _, btn in ipairs(self.buttons) do
            btn:Hide()
            btn:ClearAllPoints()
        end
    end
    wipe(self.buttons)

    for _, heirloom in ipairs(heirlooms) do
        local button
        if heirloom.name == "map" and PlayerHasToy(heirloom.id) and
            (APR.Faction == heirloom.faction or heirloom.faction == "Neutral") then
            button = self.iconButtons[heirloom.id] or CreateMapButton(HeirloomFrame_body, heirloom.id)
        elseif heirloom.name == "heirloom" then
            button = self.iconButtons[heirloom.id] or CreateHeirloomButton(HeirloomFrame_body, heirloom.icon)
        end
        if button then
            self.iconButtons[heirloom.id] = button
            button:Show()
            if APR.RegisterSkinTarget then
                APR:RegisterSkinTarget(button, "icon", { texture = button:GetNormalTexture() or button.icon })
            end
            button:SetPoint("TOPLEFT", xOffset, yOffset)
            table.insert(self.buttons, button)
            xOffset = xOffset + 62.5
            elementsCount = elementsCount + 1
            if elementsCount % maxElementsPerLine == 0 then
                xOffset = 5
                yOffset = yOffset - 52.5
            end
        end
    end

    HeirloomFrame:SetSize(250, 55 + (-yOffset))
end--[[APR_DIAG]]; APR.heirloom.AddHeirloomIcons = APRTrace("APR-Core/features/player/Heirloom.lua:166:APR.heirloom:AddHeirloomIcons#16", APR.heirloom.AddHeirloomIcons)--[[/APR_DIAG]]
